"""Standard Bloom filter and Rational Bloom filter (RBF).

The filter state is an all-zero bit array of length m (R1).  Elements are mapped
with the Kirsch-Mitzenmacher double-hashing sequence
H_{i+1}(x) = (h1(x) + i*h2(x)) & (m-1)  for i = 0, 1, 2, ... (R7, R8).

StandardBloomFilter applies the first k probes, k integer (R10).
RationalBloomFilter applies the first floor(k) probes always plus one extra
probe that is activated with probability p = k - floor(k) (Definition 1/2, R4).
Activation is deterministic per element: it compares the probe value Hr(x) with
p*m (Algorithm 1, R5).  Following Algorithm 1's suggestion
("No additional calculation needed if we, e.g., choose Hr(x) = H_floor(k)(x)")
Hr is the index of the last always-applied probe, so insertion and querying of
the same element always make the same activation decision, which preserves the
no-false-negative property (Lemma 1, R6).
"""
from __future__ import annotations

import numpy as np

import config
from hash_utils import hash_pairs, probe_matrix


class BloomFilter:
    """Standard Bloom filter with an integer number of hash functions."""

    def __init__(self, m: int, k: int, seed_h1: int = config.HASH_SEED_H1,
                 seed_h2: int = config.HASH_SEED_H2):
        if m & (m - 1):
            raise ValueError("m must be a power of two (AND-based modulo, Eqn. 3)")
        self.m = int(m)
        self.k = int(k)
        self.seed_h1 = seed_h1
        self.seed_h2 = seed_h2
        self.bits = np.zeros(self.m, dtype=bool)   # all-zero bit array, R1
        self.n_inserted = 0
        self.n_activated = 0

    # -- hashing -----------------------------------------------------------
    def hash_values(self, values):
        return hash_pairs(values, self.seed_h1, self.seed_h2)

    # -- probes ------------------------------------------------------------
    def n_probes(self) -> int:
        return self.k

    def _insert_indices(self, probes: np.ndarray) -> np.ndarray:
        """Indices to set on insertion (shape (N, j))."""
        return probes[:, :self.k]

    def _query_plan(self, probes: np.ndarray):
        """Return (required_indices, optional_indices, activation_mask)."""
        required = probes[:, :self.k]
        none = np.zeros(len(probes), dtype=bool)
        return required, probes[:, :0], none

    # -- public API --------------------------------------------------------
    def insert(self, values):
        self.insert_pairs(*self.hash_values(values))

    def insert_pairs(self, h1, h2):
        probes = probe_matrix(h1, h2, self.m, max(self.n_probes(), 1))
        idx = self._insert_indices(probes)
        self.bits[idx.ravel()] = True
        self.n_inserted = len(h1)
        return self

    def query(self, values) -> np.ndarray:
        return self.query_pairs(*self.hash_values(values))

    def query_pairs(self, h1, h2) -> np.ndarray:
        probes = probe_matrix(h1, h2, self.m, max(self.n_probes(), 1))
        required, optional, activated = self._query_plan(probes)
        present = np.ones(len(h1), dtype=bool)
        for j in range(required.shape[1]):
            present &= self.bits[required[:, j]]
        for j in range(optional.shape[1]):
            present &= ~activated | self.bits[optional[:, j]]
        return present

    # -- diagnostics -------------------------------------------------------
    @property
    def bits_set(self) -> int:
        return int(self.bits.sum())

    @property
    def fraction_of_zeros(self) -> float:
        return 1.0 - self.bits_set / self.m


class RationalBloomFilter(BloomFilter):
    """Bloom filter with a rational number of hash functions (RBF)."""

    def __init__(self, m: int, k: float, seed_h1: int = config.HASH_SEED_H1,
                 seed_h2: int = config.HASH_SEED_H2):
        super().__init__(m, int(np.floor(k)), seed_h1, seed_h2)
        self.k_rational = float(k)
        self.floor_k = int(np.floor(k))
        self.p_activation = float(k) - self.floor_k
        # number of probes that may be evaluated = floor(k) + (1 if p > 0)
        self._n_probe_slots = self.floor_k + (1 if self.p_activation > 0 else 0)

    def n_probes(self) -> int:
        return max(self.floor_k, 1)

    def _activation_probe_col(self) -> int:
        """Column of the probe matrix used as deterministic activation source Hr."""
        if self.floor_k >= 1:
            return self.floor_k - 1        # H_floor(k), the last always-applied hash
        return 1                           # no always-applied hash for k < 1

